func raceSub(i int) ReviewSubmission {
	return reviewSub("1", "0xa", "0xv", "sandwich",
		fmt.Sprintf("race-%02d", i),
		fmt.Sprintf("operator-%02d", i),
		fmt.Sprintf("reason-%02d", i),
