	recheck(conflictIdx, "conflict")
	if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
		t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
	}

	// Deterministic late entrants: a wave that starts only after the object
	// is provably at version 2. These contenders never see a held lock (the
	// race lock is long released); each acquires it, reads the already-bumped
	// version and must take the version-conflict path — including when they
	// serialize among themselves. This is the legitimate loser outcome the
	// old regression assumed could never happen, and it must append nothing.
	const lateN = 6
	var lateWG sync.WaitGroup
	lateErrs := make([]error, lateN)
	lateStart := make(chan struct{})
	for j := 0; j < lateN; j++ {
		lateWG.Add(1)
		go func(j int) {
			defer lateWG.Done()
			<-lateStart
			_, lateErrs[j] = SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
				fmt.Sprintf("late-%02d", j),
				fmt.Sprintf("late-operator-%02d", j),
				fmt.Sprintf("late-reason-%02d", j),
				contenderStatuses[j%len(contenderStatuses)], 1))
		}(j)
	}
	close(lateStart)
	lateWG.Wait()
	for j, err := range lateErrs {
		if !errors.Is(err, ErrReviewConflict) {
			t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
		}
	}

	// The follow-up conflict submissions appended nothing either.
	final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if final.Version != 2 || len(final.Revisions) != 2 || !reflect.DeepEqual(final.Revisions, hist.Revisions) {
		t.Fatalf("post-race conflict replays changed history: %+v", final)
	}
	return winner
}

