568	// contenderStatuses gives each racing submitter a status of its own; the
569	// winner revision can then be proven to carry one submitter's complete
570	// content with no fields mixed in from another contender.
571	var contenderStatuses = []string{
572		ReviewStatusFalsePositive,
573		ReviewStatusReal,
574		ReviewStatusUnreviewed,
575	}
576	
577	func raceSub(i int) ReviewSubmission {
578		return reviewSub("1", "0xa", "0xv", "sandwich",
579			fmt.Sprintf("race-%02d", i),
580			fmt.Sprintf("operator-%02d", i),
581			fmt.Sprintf("reason-%02d", i),
582			contenderStatuses[i%len(contenderStatuses)], 1)
583	}
584	
585	type raceOutcome struct {
586		res SubmitReviewResult
587		err error
588	}
589	
590	// runRejudgmentRace fires n contenders carrying the same valid
591	// expectedVersion (1, against an object already at version 1) at the same
592	// instant, each with a distinct submissionId/operator/reason/status, and
593	// returns the per-submitter outcomes in submission order.
594	func runRejudgmentRace(t *testing.T, dir string, n int) []raceOutcome {
595		t.Helper()
596		outcomes := make([]raceOutcome, n)
597		var wg sync.WaitGroup
598		start := make(chan struct{})
599		for i := 0; i < n; i++ {
600			wg.Add(1)
601			go func(i int) {
602				defer wg.Done()
603				<-start
604				outcomes[i].res, outcomes[i].err = SubmitReview(dir, raceSub(i))
605			}(i)
606		}
607		close(start)
608		wg.Wait()
609		return outcomes
610	}
611	
612	// verifyRaceSettlement proves the anti-overwrite rules against the history
613	// actually persisted after a rejudgment race: exactly one contender created
614	// a revision, the object advanced exactly one version, every stored bit of
615	// the new revision comes from that winner alone, the original revision and
616	// the archived conclusion/evidence are untouched, and every loser (busy or
617	// version conflict) left no content behind.
618	func verifyRaceSettlement(t *testing.T, dir string, outcomes []raceOutcome, original ReviewRevision) int {
619		t.Helper()
620		winner := -1
621		busyIdx, conflictIdx := -1, -1
622		for i, o := range outcomes {
623			switch {
624			case o.err == nil:
625				if !o.res.Created || o.res.Version != 2 {
626					t.Fatalf("submitter %d returned %+v, want created at version 2", i, o.res)
627				}
628				if winner != -1 {
629					t.Fatalf("two successful contenders: %d and %d", winner, i)
630				}
631				winner = i
632			case errors.Is(o.err, ErrBusy):
633				// The contender hit the lock while another submitter held it.
634				busyIdx = i
635			case errors.Is(o.err, ErrReviewConflict):
636				// The contender entered after the lock was released, read the
637				// already-bumped version and was rejected on the version check.
638				conflictIdx = i
639			default:
640				t.Fatalf("submitter %d got an outcome other than success/busy/conflict: %v", i, o.err)
641			}
642		}
643		if winner == -1 {
644			t.Fatal("no contender succeeded")
645		}
646		t.Logf("race settled: winner=%d, busy=%d, version-conflict=%d (either loser outcome is valid)",
647			winner, countOutcomes(outcomes, ErrBusy), countOutcomes(outcomes, ErrReviewConflict))
648	
649		winSub := raceSub(winner)
650		wantRev := winSub.revision(2)
651		if !reflect.DeepEqual(outcomes[winner].res.Revision, wantRev) {
652			t.Fatalf("winner result revision = %+v, want %+v", outcomes[winner].res.Revision, wantRev)
653		}
654	
655		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
656		if err != nil {
657			t.Fatal(err)
658		}
659		if hist.Version != 2 || hist.Status != winSub.Status {
660			t.Fatalf("current state = %q/%d, want %q/2 (the winner's rejudgment)",
661				hist.Status, hist.Version, winSub.Status)
662		}
663		if len(hist.Revisions) != 2 {
664			t.Fatalf("object holds %d revisions, want exactly 2 (losers must leave none): %+v",
665				len(hist.Revisions), hist.Revisions)
666		}
667		if !reflect.DeepEqual(hist.Revisions[0], original) {
668			t.Fatalf("original revision not retained first: %+v, want %+v", hist.Revisions[0], original)
669		}
670		if !reflect.DeepEqual(hist.Revisions[1], wantRev) {
671			t.Fatalf("appended revision = %+v, want the winner's %+v", hist.Revisions[1], wantRev)
672		}
673		// Defense in depth: no field of any loser may appear in the new
674		// revision, and no loser submission id may be stored anywhere. Status is
675		// deliberately excluded because only three legal statuses exist so two
676		// contenders may legitimately carry the same one; identity/operator/
677		// reason are unique per submitter and the full-revision DeepEqual above
678		// already pins the winner's status.
679		loserIDs := map[string]bool{}
680		for i := range outcomes {
681			if i == winner {
682				continue
683			}
684			s := raceSub(i)
685			loserIDs[s.SubmissionID] = true
686			stored := hist.Revisions[1]
687			if stored.SubmissionID == s.SubmissionID || stored.Operator == s.Operator ||
688				stored.Reason == s.Reason {
689				t.Fatalf("loser %d content mixed into the stored revision: %+v", i, stored)
690			}
691			if reflect.DeepEqual(stored, s.revision(2)) {
692				t.Fatalf("stored revision is identical to loser %d's content: %+v", i, stored)
693			}
694		}
695		for _, rev := range hist.Revisions {
696			if loserIDs[rev.SubmissionID] {
697				t.Fatalf("loser submission id %q left a revision", rev.SubmissionID)
698			}
699		}
700		// The original archived conclusion, its detection parameters and the
701		// raw swap evidence stay exactly as archived.
702		if hist.Original == nil ||
703			hist.Original.Finding.TxHash != "0xv" || hist.Original.Finding.Kind != "sandwich" ||
704			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
705			t.Fatalf("original conclusion/evidence changed: %+v", hist.Original)
706		}
707		if hist.Original.Version.ID != BuiltinVersionID {
708			t.Fatalf("detection version changed: %+v", hist.Original.Version)
709		}
710	
711		// After the race, resubmitting with the stale expected version must be a
712		// version conflict regardless of how the contender originally lost: a
713		// busy loss is not a completed rejudgment, and neither path may overwrite
714		// the winner.
715		recheck := func(idx int, label string) {
716			if idx < 0 {
717				return
718			}
719			if _, err := SubmitReview(dir, raceSub(idx)); !errors.Is(err, ErrReviewConflict) {
720				t.Fatalf("%s loser (submitter %d) replayed with original expected version: got %v, want ErrReviewConflict",
721					label, idx, err)
722			}
723		}
724		recheck(busyIdx, "busy")
725		recheck(conflictIdx, "conflict")
726		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
727			t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
728		}
729	
730		// Deterministic late entrants: sequential submissions issued only after
731		// the object is provably at version 2 and the race lock is long released.
732		// Each acquires the free lock, reads the already-bumped version and must
733		// take the version-conflict path (never busy, since submissions are
734		// serialized here). This is the legitimate loser outcome the old
735		// regression assumed could never happen, and it must append nothing.
736		const lateN = 6
737		for j := 0; j < lateN; j++ {
738			_, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
739				fmt.Sprintf("late-%02d", j),
740				fmt.Sprintf("late-operator-%02d", j),
741				fmt.Sprintf("late-reason-%02d", j),
742				contenderStatuses[j%len(contenderStatuses)], 1))
743			if !errors.Is(err, ErrReviewConflict) {
744				t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
745			}
746		}
747	
748		// The follow-up conflict submissions appended nothing either.
749		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
750		if err != nil {
